        data = json.loads(json_text, parse_constant=_reject_constant)
    except (ValueError, TypeError, RecursionError):
        return None
    if not isinstance(data, list):
        return None
    common = None
    for item in data:
        if not isinstance(item, dict):
            return None
        keys = set(item.keys())
        if common is None:
            common = keys
        else:
            common &= keys
    if common is None:
        return []
    return sorted(common)

