import math


def ranked_root_gaps(values):
    vals = list(values)
    if len(vals) < 2:
        return []
    triples = []
    for i in range(len(vals) - 1):
        a = vals[i]
        b = vals[i + 1]
        r = math.sqrt(abs(a - b))
        triples.append((a, b, r))
    # sorted is stable, so ties keep their original input order
    return sorted(triples, key=lambda t: t[2], reverse=True)

