import re

_WORD_RE = re.compile(r'\w+')


def _rotate(match, shift):
    word = match.group(0)
    if len(word) <= 3:
        return word
    interior = word[1:-1]
    n = len(interior)
    k = shift % n
    return word[0] + interior[k:] + interior[:k] + word[-1]


def rotate_word_interiors(text, shift):
    return _WORD_RE.sub(lambda m: _rotate(m, shift), text)

