        raise ValueError('invalid start time: %r' % (start,))
    try:
        current = datetime.strptime(start, '%Y-%m-%d %H:%M')
    except (ValueError, TypeError):
        raise ValueError('invalid start time: %r' % (start,))
    if conditions is None:
        raise ValueError('conditions must be a list')
    conds = list(conditions)
    for c in conds:
        if not isinstance(c, str) or c not in _ALLOWED:
            raise ValueError('invalid condition: %r' % (c,))
    lines = ['Time,Condition']
    step = timedelta(hours=1)
    for i, c in enumerate(conds):
        if i > 0:
            try:
                current = current + step
            except OverflowError:
                raise ValueError('time out of range')
        lines.append(_fmt(current) + ',' + c)
    return '\n'.join(lines) + '\n'

