import ipaddress
import re


def _parse_network(ip_range):
    if not isinstance(ip_range, str):
        raise ValueError("ip_range must be a string in IPv4 CIDR notation")
    parts = ip_range.split('/')
    if len(parts) != 2:
        raise ValueError("invalid IPv4 CIDR network: %r" % (ip_range,))
    addr_part, prefix_part = parts
    if not re.fullmatch(r'[0-9]{1,2}', prefix_part):
        raise ValueError("invalid prefix length in %r" % (ip_range,))
    if int(prefix_part) > 32:
        raise ValueError("invalid prefix length in %r" % (ip_range,))
    try:
        ipaddress.IPv4Address(addr_part)
    except (ValueError, TypeError):
        raise ValueError("invalid IPv4 address in %r" % (ip_range,))
    try:
        return ipaddress.IPv4Network(ip_range, strict=True)
    except (ValueError, TypeError) as exc:
        raise ValueError("invalid IPv4 CIDR network %r: %s" % (ip_range, exc))


def port_status_map(ip_range, port, open_services):
    network = _parse_network(ip_range)
    result = dict.fromkeys((str(a) for a in network), False)
    if not open_services:
        return result
    for host, ports in open_services.items():
        try:
            addr = ipaddress.IPv4Address(host if not isinstance(host, str) else host.strip())
        except (ValueError, TypeError):
            continue
        if addr not in network:
            continue
        if not ports:
            continue
        try:
            is_open = port in ports
        except TypeError:
            is_open = False
        if is_open:
            result[str(addr)] = True
    return result

