import re

_DRIVE_RE = re.compile(r'^[A-Za-z]:')


def plan_archive_extraction(target_dir, member_names):
    if not target_dir:
        raise ValueError('target_dir must be a non-empty string')
    base = target_dir.rstrip('/')
    result = []
    for name in member_names:
        if name.endswith('/') or name.endswith('\\'):
            continue
        path = name.replace('\\', '/')
        if path.startswith('/') or _DRIVE_RE.match(path):
            raise ValueError('absolute member path: %r' % (name,))
        norm = posixpath.normpath(path)
        if norm in ('.', '..') or norm.startswith('../') or norm.startswith('/'):
            raise ValueError('member path escapes target directory: %r' % (name,))
        result.append((name, base + '/' + norm))
    return result

