import csv
import io


def summarize_timesheet(csv_text, id_prefix):
    if csv_text is None:
        csv_text = ""
    reader = csv.reader(io.StringIO(csv_text, newline=""))

    def is_blank(row):
        return not row or all(f.strip() == "" for f in row)

    header = None
    for row in reader:
        if is_blank(row):
            continue
        header = row
        break
    if header is None:
        raise ValueError("missing header")

    names = [h.strip() for h in header]
    if names:
        names[0] = names[0].lstrip("\ufeff").strip()
    if "employee_id" not in names or "hours" not in names:
        raise ValueError("header must contain 'employee_id' and 'hours' columns")
    id_idx = names.index("employee_id")
    hours_idx = names.index("hours")
    needed = max(id_idx, hours_idx)

    prefix = id_prefix or ""
    result = {}
    for row in reader:
        if is_blank(row):
            continue
        if len(row) <= needed:
            raise ValueError("row has too few fields: %r" % (row,))
        emp = row[id_idx].strip()
        if not emp.startswith(prefix):
            continue
        try:
            hours = float(row[hours_idx].strip())
        except ValueError:
            raise ValueError("invalid hours value: %r" % (row[hours_idx],))
        count, total = result.get(emp, (0, 0.0))
        result[emp] = (count + 1, total + hours)
    return result

